local config = {
  ui_story_5003_50030101_1_dialog_content = "PlayerName, we're under attack by a swarm of Eclipsites! We can't stay this low!",
  ui_story_5003_50030101_2_dialog_content = "What the—!? We've got Eclipsites all over the Colossus! There are too many of them!",
  ui_story_5003_50030101_3_dialog_content = "Forget about landing for now... Let's head straight for Cloud Mountain!",
  ui_story_5003_50030101_4_dialog_content = "Got it! Getting ready for take off!",
  ui_story_5003_50030101_5_dialog_content = "I'm sorry. This whole mess was my fault.",
  ui_story_5003_50030101_6_dialog_content = "It's not your fault, Hiiro.",
  ui_story_5003_50030101_7_dialog_content = "<color=#e8d9bb>Three days ago.</color>",
  ui_story_5003_50030101_8_dialog_content = "Uh-oh... PlayerName, Commander Hiiro's come looking for us!",
  ui_story_5003_50030101_9_dialog_content = "What's the big deal, Vice? Why are you so agitated?",
  ui_story_5003_50030101_10_dialog_content = "To be honest, I've never seen Commander Hiiro ask for help with personal matters before. This must be serious...",
  ui_story_5003_50030101_11_dialog_content = "I'm sorry for imposing on you like this. Could you grant me passage on the Colossus and take me to a destination?",
  ui_story_5003_50030101_12_dialog_content = "Of course... But can I ask what this is all about?",
  ui_story_5003_50030101_13_dialog_content = "<color=#FFB400>Something strange</color> has happened to my Sakae Blade. I wish to investigate the matter.",
  ui_story_5003_50030101_14_dialog_content = "I don't have much time to spare, so I hope to start the investigation immediately.",
  ui_story_5003_50030101_15_dialog_content = "Is it really that urgent? I was hoping to make some adjustments to the Colossus before taking off...",
  ui_story_5003_50030101_16_dialog_content = "Well, I mean it's not that easy for a Legion Commander to apply for leave like this.",
  ui_story_5003_50030101_17_dialog_content = "Well, it's just routine maintenance anyway, so I guess it should be fine if I put it off for now. So, where do you want to go?",
  ui_story_5003_50030101_18_dialog_content = "To the east... To Cloud Mountain.",
  ui_story_5003_50030101_19_dialog_content = "A land covered with snow all year round, where cherry blossoms often bloom, injecting color into the pure white landscape...",
  ui_story_5003_50030101_x19_dialog_content = "My hometown.",
  ui_story_5003_50030101_S19_dialog_content = "Wisps spiral and ascend in the East\nUpon a distant mountain peak\nCloud Mountain, where eons ago\nA deity did a treasure bestow\nTo protect the region from Eclipsite wrath\nThough the peace it brought could never last\nNow tensions mount and factions rise\nThe treasure falls prey to covetous eyes\nAs the clutch of chaos grips the land\nThe dawn of war is close at hand\n— A View from Cloud Mountain",
  ui_story_5003_50030101_20_dialog_content = "This is Cloud Mountain... Look at all these huge cabins!",
  ui_story_5003_50030101_21_dialog_content = "I know it's exciting to be in a new place, but seriously, focus!",
  ui_story_5003_50030101_22_dialog_content = "This is the legendary Cloud Mountain...? What was it you said about this place last time?",
  ui_story_5003_50030101_23_dialog_content = "Cloud Mountain is a town on an island in the Far East. It's perennially covered in snow and is famous for hot springs.",
  ui_story_5003_50030101_24_dialog_content = "This region is known for the cherry blossoms during the snow season. The snow covers the branches of the cherry trees like clouds, which is why it's also called Cloud Blossom Mountain!",
  ui_story_5003_50030101_25_dialog_content = "Yes, that's right. That exactly what I wanted to see...",
  ui_story_5003_50030101_26_dialog_content = "But what about that huge swarm of Eclipsites outside Cloud Mountain? They pounced on us before we can even land!",
  ui_story_5003_50030101_27_dialog_content = "The Eclipsites have been quite active around Cloud Mountain, but there weren't so many of them around here before.",
  ui_story_5003_50030101_28_dialog_content = "Perhaps there's a sudden increase in Eclipsite activity just like the rest of Astra?",
  ui_story_5003_50030101_29_dialog_content = "Hmm, perhaps. But don't worry, they won't disturb us.",
  ui_story_5003_50030101_30_dialog_content = "Why?",
  ui_story_5003_50030101_31_dialog_content = "Legend says that <color=#FFB400>Cloud Mountain is protected by a magical barrier</color>. The Eclipsites fear its power and do not dare to enter.",
  ui_story_5003_50030101_32_dialog_content = "Gaah... Graaah... Groooar!",
  ui_story_5003_50030101_33_dialog_content = "Hiiro... Did you just say the Eclipsites do not dare to enter?",
  ui_story_5003_50030101_34_dialog_content = "Yes, the Eclipsites will not take the initiative to invade Cloud Mountain while it is protected by the barrier, unless...",
  ui_story_5003_50030101_35_dialog_content = "Unless we brought those Eclipsites in with us!?",
  ui_story_5003_50030101_36_dialog_content = "*Roaring*",
  ui_story_5003_50030101_37_dialog_content = "Now that's slightly more than we can handle, don't you think!?",
  ui_story_5003_50030101_38_dialog_content = "Watch out, Commander Hiiro!",
  ui_story_5003_50030101_39_dialog_content = "Graaah—!",
  ui_story_5003_50030101_40_dialog_content = "Ugh!",
  ui_story_5003_50030101_41_dialog_content = "Step aside!",
  ui_story_5003_50030101_42_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030101_43_dialog_content = "What's the meaning of this, bringing these Eclipsites here so early in the morning...?",
  ui_story_5003_50030101_44_dialog_content = "This is all a misunderstanding. We were besieged by Eclipsites outside and had no choice but to enter.",
  ui_story_5003_50030101_45_dialog_content = "What's the huge thing that landed out there in the open? A Caelestite Colossus?!",
  ui_story_5003_50030101_46_dialog_content = "You know what a Colossus is?!",
  ui_story_5003_50030101_47_dialog_content = "*Roaring*",
  ui_story_5003_50030101_48_dialog_content = "Let's get rid of these Eclipsites first! Don't let them reach the streets!",
  ui_story_5003_50030101_49_dialog_content = "Urgh...",
  ui_story_5003_50030101_50_dialog_content = "It's so rare to have a break, there have sure been a lot of surprises lately.",
  ui_story_5003_50030101_51_dialog_content = "I don't know who you are, but thank you for your help.",
  ui_story_5003_50030101_52_dialog_content = "My name is Vice, and this is PlayerName and Hiiro, my commander.",
  ui_story_5003_50030101_53_dialog_content = "I know.",
  ui_story_5003_50030101_54_dialog_content = "Huh?",
  ui_story_5003_50030101_55_dialog_content = "Now that I've helped you, it wouldn't be too much to ask for some compensation, would it?",
  ui_story_5003_50030101_56_dialog_content = "... I'm responsible for this matter. Please, name your price.",
  ui_story_5003_50030101_57_dialog_content = "I wasn't looking for you. You over there—disciple of the Sakae Family! Come and show me what you've got!",
  ui_story_5003_50030101_58_dialog_content = "Disciple of the Sakae Family... Who are you?",
  ui_story_5003_50030101_59_dialog_content = "It doesn't matter who I am, what matters is that you recognize my technique.",
  ui_story_5003_50030101_60_dialog_content = "These techniques are undeniably the same, but I never expected a disciple of Sakae to return to Cloud Mountain.",
  ui_story_5003_50030101_61_dialog_content = "Hah! You came back too, didn't you?",
  ui_story_5003_50030101_62_dialog_content = "<color=#e8d9bb>Clang—!</color>",
  ui_story_5003_50030101_63_dialog_content = "Well, that was disappointing... Why are you so weak?",
  ui_story_5003_50030101_64_dialog_content = "...",
  ui_story_5003_50030101_65_dialog_content = "What do you know? Commander Hiiro hasn't rested properly in ages! If she had, she would have had the upper hand!",
  ui_story_5003_50030101_66_dialog_content = "Vice, please... Say no more.",
  ui_story_5003_50030101_67_dialog_content = "What a disappointment. Next time, get yourself together. Don't bring shame to the <color=#FFB400>Sakae Dojo</color>.",
  ui_story_5003_50030101_68_dialog_content = "Wait a minute. If you're a disciple of the Sakae Family, do you know how the dojo is doing these days?",
  ui_story_5003_50030101_69_dialog_content = "I know what you're worried about.",
  ui_story_5003_50030101_70_dialog_content = "It's alright. Cloud Mountain is <color=#FFB400>safe for us</color> now.",
  ui_story_5003_50030101_71_dialog_content = "It's safe...?",
  ui_story_5003_50030101_72_dialog_content = "Hiiro, are you alright? That strange man left already...",
  ui_story_5003_50030101_73_dialog_content = "I'm fine. Let's go to the dojo first. That is the main purpose of our trip, after all.",
  ui_story_5003_50030101_74_dialog_content = "About that strange man just now...",
  ui_story_5003_50030101_75_dialog_content = "Do you know him?",
  ui_story_5003_50030101_76_dialog_content = "No, I don't know him, but I'm certain I know his combat style.",
  ui_story_5003_50030101_77_dialog_content = "He seems to be connected with the Sakae Family. I believe we may meet again.",
  ui_story_5003_50030101_78_dialog_content = "Sure.",
  ui_story_5003_50030101_79_dialog_content = "Run, Hiiro! Quickly—follow me!",
  ui_story_5003_50030101_80_dialog_content = "Master...?",
  ui_story_5003_50030101_81_dialog_content = "They're coming! Move it! Get out of the dojo!",
  ui_story_5003_50030101_82_dialog_content = "The Sakae Dojo... It's definitely here.",
  ui_story_5003_50030101_83_dialog_content = "But why is it...",
  ui_story_5003_50030101_84_dialog_content = "Welcome to Cwoud Bwossom Hotel!",
  ui_story_5003_50030101_85_dialog_content = "Who are you? What's going on here?",
  ui_story_5003_50030101_86_dialog_content = "Ah, guests! Any longer and I would have forgots how to weceive guests by now!",
  ui_story_5003_50030101_87_dialog_content = "Ah, where are my manners! I forgots to intwoduce myself. My name is Tweety. The hotel's fwedgling receptionist!",
  ui_story_5003_50030101_88_dialog_content = "I'm sorry... I can't seem to understand what she's saying.",
  ui_story_5003_50030101_89_dialog_content = "Snow pwoblem, I just gots a wittle accent. Pwease come in!",
  ui_story_5003_50030101_90_dialog_content = "I think she said... She has an accent?",
  ui_story_5003_50030101_91_dialog_content = "Hmm. This the local accent here on Cloud Mountain.",
  ui_story_5003_50030101_92_dialog_content = "Tweety, is this a hot spring hotel?",
  ui_story_5003_50030101_93_dialog_content = "That's wight! This is a pecktacular pwace to stay! We gots gweat food, lodging, and hotsprings. We even pwovide yukatas!",
  ui_story_5003_50030101_94_dialog_content = "Huh? What did she say?",
  ui_story_5003_50030101_95_dialog_content = "She said, \"The lodgings and hot springs here are wonderful. We also provide yukatas.\"",
  ui_story_5003_50030101_96_dialog_content = "Thank you, cherry blossom wady! I will twy to tone down my accent.",
  ui_story_5003_50030101_97_dialog_content = "But it's too hawd. I'm reawwy sowwy!",
  ui_story_5003_50030101_98_dialog_content = "No, you have no reason to apologize.",
  ui_story_5003_50030101_99_dialog_content = "Hearing this familiar accent soothes me.",
  ui_story_5003_50030101_100_dialog_content = "Reawwy? Spwendid!",
  ui_story_5003_50030101_101_dialog_content = "Pwease enjoy your stay!",
  ui_story_5003_50030101_102_dialog_content = "Enjoy your stay...? I'm sorry, but we're not here for fun, but to investigate some matters.",
  ui_story_5003_50030101_103_dialog_content = "Eh? I knows that mark! Miss chewwy bwossom, are you fwom Illumina? What a sight for soar eyes!",
  ui_story_5003_50030101_104_dialog_content = "Wait.. You mean this symbol? You know Illumina?",
  ui_story_5003_50030101_105_dialog_content = "Huh? When did she say Illumina? How come the people here know about Illumina?",
  ui_story_5003_50030101_106_dialog_content = "I knows Illumina!",
  ui_story_5003_50030101_108_dialog_content = "Your pronunciation of \"Illumina\" is very good. So, you really know Illumina, huh?",
  ui_story_5003_50030101_109_dialog_content = "Is Illumina well-known here on Cloud Mountain?",
  ui_story_5003_50030101_110_dialog_content = "Not reawwy. I onwy know because I used to work there. Awe you fwom there as well?",
  ui_story_5003_50030101_111_dialog_content = "Huh? As well?",
  ui_story_5003_50030101_112_dialog_content = "Why do you wook so surpwised? I'm pawt of the Couwier Union, too!",
  ui_story_5003_50030101_113_dialog_content = "You are from the <color=#FFB400>Courier Union</color>?",
  ui_story_5003_50030101_X113_dialog_content = "Yes!",
  ui_story_5003_50030101_114_dialog_content = "The Courier Union? Yes, we know it too well.",
  ui_story_5003_50030101_X114_dialog_content = "And look, the kid does have a bird's tail!!",
  ui_story_5003_50030101_115_dialog_content = "Chirp! Why're you acting cuckoo aww of a sudden?",
  ui_story_5003_50030101_116_dialog_content = "Erm, sorry... PlayerName was looking for something \"exotic\" during this trip.",
  ui_story_5003_50030101_117_dialog_content = "PlayerName got a little excited because everything seems all too \"familiar.\"",
  ui_story_5003_50030101_118_dialog_content = "Ah, I see! You awe fwiends of the Couwier Union? How wonderful!",
  ui_story_5003_50030101_119_dialog_content = "Sorry, I'll try to calm down, but Hiiro... What are we going to do now?",
  ui_story_5003_50030101_120_dialog_content = "I suppose we can trust a member of the Courier Union.",
  ui_story_5003_50030101_121_dialog_content = "Let's stay a while first and see what's really going on here.",
  ui_story_5003_50030101_122_dialog_content = "I need to know... Why is this place now a hotel?",
  ui_story_5003_50030201_1_dialog_content = "Will you be at the hotel for dinner later, Sanki?",
  ui_story_5003_50030201_2_dialog_content = "I got some good ingredients for you today.",
  ui_story_5003_50030201_3_dialog_content = "No... There are guests at the hotel. You should go back now.",
  ui_story_5003_50030201_4_dialog_content = "Eh? Leaving already?",
  ui_story_5003_50030201_5_dialog_content = "Ah... This kid. Still so cold even after so many days we've been together.",
  ui_story_5003_50030201_6_dialog_content = "It's yukata time!",
  ui_story_5003_50030201_7_dialog_content = "Oh! So, these are the yukatas Hiiro was talking about!",
  ui_story_5003_50030201_8_dialog_content = "You all look reawwy beautiful in those yukatas!",
  ui_story_5003_50030201_9_dialog_content = "Thank you! But, Tweety, if you're a member of the Courier Union, what are you doing working on Cloud Mountain?",
  ui_story_5003_50030201_10_dialog_content = "My parents worked on the continent when I was a wittle hatchling, and our neighbor Gwammy took care of me!",
  ui_story_5003_50030201_11_dialog_content = "I'm not working. Gwammy tweets me like her own gwanddaughter, so I come and help out at the hotel on my breaks!",
  ui_story_5003_50030201_12_dialog_content = "I see.",
  ui_story_5003_50030201_13_option_content = [[
I'm sorry... 
I'm getting confused again.]],
  ui_story_5003_50030201_14_dialog_content = "This is giving me a headache.",
  ui_story_5003_50030201_15_option_content = [[
Vice, are you used to her accent
already?]],
  ui_story_5003_50030201_16_dialog_content = "Haha, I think I can pretty much understand it now!",
  ui_story_5003_50030201_17_dialog_content = "She said, \"Granny treats me like a granddaughter, so of course I should come back and help her with the hotel when I'm on vacation.\"",
  ui_story_5003_50030201_18_dialog_content = "I'm back.",
  ui_story_5003_50030201_19_dialog_content = "Welcome to our hotel. Sorry, had to go out just now, so I couldn't greet you.",
  ui_story_5003_50030201_20_dialog_content = "Gwammy is in chawge of this hotel!",
  ui_story_5003_50030201_21_dialog_content = "Excuse me, ma'am, are you from the Astra mainland, too?",
  ui_story_5003_50030201_22_dialog_content = "No, I was born and raised here on Cloud Mountain.",
  ui_story_5003_50030201_23_dialog_content = "Do you know who we are?",
  ui_story_5003_50030201_24_dialog_content = "This is the first time we've met.",
  ui_story_5003_50030201_25_dialog_content = "Great! Looks like you're a local despite your fluent Universese!",
  ui_story_5003_50030201_26_dialog_content = "Haha, you're a funny one.",
  ui_story_5003_50030201_27_dialog_content = "Sorry, this is our first time here. We're not too familiar with this place, so we might have asked too many questions.",
  ui_story_5003_50030201_28_dialog_content = "There's no need to be polite. You're guests of the Cloud Blossom Hotel, so please feel free to ask me anything.",
  ui_story_5003_50030201_29_dialog_content = "Well, can we ask you something about the Sakae Dojo?",
  ui_story_5003_50030201_30_dialog_content = "The Sakae Dojo? Just who are you?",
  ui_story_5003_50030201_31_dialog_content = "It doesn't matter who I am. I just heard that this place was originally a dojo... and I got a little curious.",
  ui_story_5003_50030201_32_dialog_content = "I'm sorry, dear guest, although I run the hotel...",
  ui_story_5003_50030201_33_dialog_content = "I'm not actually the owner, and I don't know much about that dojo.",
  ui_story_5003_50030201_34_dialog_content = "When I came here, the dojo had already disappeared, leaving only a patch of open land.",
  ui_story_5003_50030201_35_dialog_content = "My dear guest, could I please know your name?",
  ui_story_5003_50030201_36_dialog_content = "I can ask around for you. If anything comes up, I'll let you know.",
  ui_story_5003_50030201_37_dialog_content = "Alright. My name is Hiiro.",
  ui_story_5003_50030201_38_dialog_content = "Hiiro... What a wonderful name.",
  ui_story_5003_50030201_39_dialog_content = "Tweety, have you checked in our guests and asked how long they plan to stay?",
  ui_story_5003_50030201_40_dialog_content = "All checked in for thwee days!",
  ui_story_5003_50030201_41_dialog_content = "Alright. Let's hope our guests can keep a low profile for the next three days...",
  ui_story_5003_50030201_42_dialog_content = "I assure you, we <color=#FFB400>will not disturb anyone unrelated to this matter</color>.",
  ui_story_5003_50030201_43_dialog_content = "In addition, please keep quiet about us being here.",
  ui_story_5003_50030201_44_dialog_content = "Of course, we never disclose our guests' information to anyone. Please rest assured.",
  ui_story_5003_50030201_45_dialog_content = "You can also go to Spa Street and ask around there. Maybe you'll find the information you seek.",
  ui_story_5003_50030201_46_dialog_content = "We walked around the street all day but found nothing...",
  ui_story_5003_50030201_47_dialog_content = "Commander Hiiro, should we go back and rest first before we continue?",
  ui_story_5003_50030201_48_dialog_content = "Otherwise, there might be another situation like this morning...",
  ui_story_5003_50030201_49_dialog_content = "Are you worried that if I face another challenge in my current condition, I might lose again?",
  ui_story_5003_50030201_50_dialog_content = "Sorry.",
  ui_story_5003_50030201_51_dialog_content = "No, no... There's no need to apologize. You were right to worry. Let's go back and have a good rest today.",
  ui_story_5003_50030201_52_dialog_content = "That's a \"hot spring\" for you. It seems to have rejuvenating properties.",
  ui_story_5003_50030201_53_dialog_content = "Isn't the temperature different from what Vice said before? I feel a little dizzy...",
  ui_story_5003_50030201_54_dialog_content = "Didn't you just arrive at the spring?",
  ui_story_5003_50030201_55_dialog_content = "Yeah... I always take really quick baths.",
  ui_story_5003_50030201_56_dialog_content = "Ah, wait! Aren't you the one from before? The one who suddenly started <color=#FFB400>a duel with Hiiro</color>!",
  ui_story_5003_50030201_57_dialog_content = "You mean the one with pink hair?",
  ui_story_5003_50030201_58_dialog_content = "What are you doing here? What do you want?",
  ui_story_5003_50030201_59_dialog_content = "It's called <color=#FFB400>\"sparring\"</color>, not \"dueling.\" Do you really need to be so afraid of me?",
  ui_story_5003_50030201_60_dialog_content = "I don't often come across fellow disciples. It's only natural that we should spar... and didn't that Hiiro also agree to it?",
  ui_story_5003_50030201_61_dialog_content = "Huh? I guess that... kind of makes sense?",
  ui_story_5003_50030201_62_dialog_content = "Vice, don't play with the yukata.",
  ui_story_5003_50030201_63_dialog_content = "You should relax once in a while, Commander Hiiro! Don't be so uptight!",
  ui_story_5003_50030201_64_dialog_content = "Are those... voices coming from the women's bath? Seems like this place isn't very soundproof...",
  ui_story_5003_50030201_65_dialog_content = "Not at all...",
  ui_story_5003_50030201_66_dialog_content = "Then let's talk somewhere else.",
  ui_story_5003_50030201_67_dialog_content = "Speaking of which, Commander Hiiro is just like a cherry blossom.",
  ui_story_5003_50030201_68_dialog_content = "I agwee! Hiiwo's just as you said!",
  ui_story_5003_50030201_69_dialog_content = "Maybe it's because I'm a member of the <color=#FFB400>Sakura Family</color>.",
  ui_story_5003_50030201_70_dialog_content = "The Sakuwa famiwy? I heard it fwom Gwammy. That's one <color=#FFB400>mysterious and powerful</color> famiwy.",
  ui_story_5003_50030201_71_dialog_content = "But the Sakuwas are... Didn't they disappear a wong time ago?",
  ui_story_5003_50030201_72_dialog_content = "Indeed. They vanished a long time ago... The Sakuras' time was brief, but they faced death with unflinching bravery.",
  ui_story_5003_50030201_73_dialog_content = "I was already the last of my line long before I came of age.",
  ui_story_5003_50030201_74_dialog_content = "I'm sowwy... I didn't mean to bwing up such a sad memowy...",
  ui_story_5003_50030201_75_dialog_content = "Don't worry. It's not a particularly sad memory for me.",
  ui_story_5003_50030201_76_dialog_content = "I was raised by my master, so I remember much about the Sakura Family.",
  ui_story_5003_50030201_77_dialog_content = "My master is the closest thing to a family to me... So I'm not very concerned with my birth family.",
  ui_story_5003_50030201_78_dialog_content = "Besides, being able to return to my hometown like this and see the cherry blossoms here is good enough for me.",
  ui_story_5003_50030201_79_dialog_content = "Sorry, I thought you followed us into the hotel.",
  ui_story_5003_50030201_80_dialog_content = "But come to think of it, you're wearing a yukata... So you must be a guest here.",
  ui_story_5003_50030201_81_dialog_content = "Yes. But to be precise, I am an investor in this hotel. Here's my business card.",
  ui_story_5003_50030201_82_dialog_content = "You're one of the hotel's investors? But your business card says you work in Umbraton!?",
  ui_story_5003_50030201_83_dialog_content = "You can just call me Taki. I have a company in Umbraton. You can come and find me if you ever have business there in the future.",
  ui_story_5003_50030201_84_dialog_content = "I was surprised enough to find out Tweety's from the Courier Union, and now you're from Astra.",
  ui_story_5003_50030201_X84_dialog_content = "But now I suddenly feel that meeting people from somewhere familiar it's actually quite comforting.",
  ui_story_5003_50030201_85_dialog_content = "I'm PlayerName. I'm glad I met you like this, as I'm certain you'll make our investigation here all that much easier.",
  ui_story_5003_50030201_86_dialog_content = "Hmm, that's an interesting idea. I might just hold you to it and ask you to pay up.",
  ui_story_5003_50030201_87_dialog_content = "Does that include consultations as well?",
  ui_story_5003_50030201_88_dialog_content = "Now, now, that's enough of that. Hiiro and I are both from Sakae Dojo, you know that, right?",
  ui_story_5003_50030201_89_dialog_content = "I know... Hiiro told us something about the dojo.",
  ui_story_5003_50030201_90_dialog_content = "Hmm, it seems you people are someone I can trust.",
  ui_story_5003_50030201_91_dialog_content = "<anim type=Shake><color=#e8d9bb>*Whoosh*—</color></anim>",
  ui_story_5003_50030201_92_dialog_content = "Hey, did someone just run outside?",
  ui_story_5003_50030201_93_dialog_content = "Huh? Who?",
  ui_story_5003_50030201_94_dialog_content = "I don't know. I didn't recognize them.",
  ui_story_5003_50030201_95_dialog_content = "I'll take a look!",
  ui_story_5003_50030201_96_dialog_content = "<size=30>Huh? You mean someone just...</size>",
  ui_story_5003_50030201_97_dialog_content = "(Vice and the others seem to be talking about something in the women's baths.)",
  ui_story_5003_50030201_98_dialog_content = "<size=30>Shh! What's the noise outside? Tweety, don't go out there just yet. Let's go...</size>",
  ui_story_5003_50030201_99_dialog_content = "Vice, are you guys alright in there?",
  ui_story_5003_50030201_100_dialog_content = "PlayerName? You...",
  ui_story_5003_50030201_101_dialog_content = "I just came in from outside to see if there was anything wrong.",
  ui_story_5003_50030201_102_dialog_content = "Trying to sneak a peek? I never would've expected...",
  ui_story_5003_50030201_103_dialog_content = "Huh? What's wrong?",
  ui_story_5003_50030201_104_dialog_content = "Eh-eh-eh? Were you twying to peep?",
  ui_story_5003_50030201_105_dialog_content = "Peep? No, that's not it at all! I didn't look inside!",
  ui_story_5003_50030201_106_dialog_content = "I just saw a suspicious person running outside, so I came in to see what happened.",
  ui_story_5003_50030201_107_dialog_content = "It's just that this place isn't that soundproof. I accidentally heard...",
  ui_story_5003_50030201_108_dialog_content = "What did you hear?",
  ui_story_5003_50030201_109_dialog_content = "First, I heard, \"Don't play with the yukata.\" No, I really wasn't eavesdropping!",
  ui_story_5003_50030201_110_dialog_content = "PlayerName! Tell us the truth!",
  ui_story_5003_50030201_111_dialog_content = "Wait! Vice! I really didn't peek!",
  ui_story_5003_50030201_112_dialog_content = "So, who was it peeking from outside?",
  ui_story_5003_50030201_113_dialog_content = "I think... it was a kid?",
  ui_story_5003_50030201_114_dialog_content = "You mean a kid like you!?",
  ui_story_5003_50030201_115_dialog_content = "No! I think the person who came out of the hotel was actually peeping!",
  ui_story_5003_50030201_116_dialog_content = "I remember seeing a topless boy with long hair... Maybe he was from Spa Street!",
  ui_story_5003_50030201_117_dialog_content = "We don't even have any girls with long hair here...",
  ui_story_5003_50030201_118_dialog_content = "PlayerName, you're not lying to me, are you?",
  ui_story_5003_50030201_119_dialog_content = "Of course I'm not!",
  ui_story_5003_50030201_X119_dialog_content = "Just wait. I'm sure I can recognize him if I see him again. Let's go confront him together!",
  ui_story_5003_50030301_1_dialog_content = "Master, why did the people turn against the dojo?",
  ui_story_5003_50030301_2_dialog_content = "When we are faced with a crisis, we all do what we can to survive.",
  ui_story_5003_50030301_3_dialog_content = "If the will to survive is concentrated on one particular thing, it may lead to conflict.",
  ui_story_5003_50030301_4_dialog_content = "We escape to get away from those dangerous conflicts.",
  ui_story_5003_50030301_5_dialog_content = "But you always taught me never to be afraid of death and to fight bravely until the last... But, Master... we ran away?",
  ui_story_5003_50030301_6_dialog_content = "Running away is not always an act of cowardice and nor is it an abandonment of one's responsibility. The reason I did what I did...",
  ui_story_5003_50030301_7_dialog_content = "It's because I had something more important to protect. I had to keep the <color=#FFB400>key</color> safe, Hiiro.",
  ui_story_5003_50030301_8_dialog_content = "When will we return? When the conflicts are over?",
  ui_story_5003_50030301_9_dialog_content = "Hiiro, we're not going back...",
  ui_story_5003_50030301_10_dialog_content = "Commander Hiiro, are you alright? Having trouble sleeping well again?",
  ui_story_5003_50030301_11_dialog_content = "No, I'm fine. I was just thinking about something.",
  ui_story_5003_50030301_12_dialog_content = "You're all up so early! I'm sorry, I haven't had time to prepare breakfast for you.",
  ui_story_5003_50030301_13_dialog_content = "Sorry, ma'am. We planned to set out earlier and hadn't planned on disturbing you.",
  ui_story_5003_50030301_14_dialog_content = "Please, don't say that. This is all part of the service here.",
  ui_story_5003_50030301_15_dialog_content = "Don't worry about us. There's something we must investigate out on the streets.",
  ui_story_5003_50030301_16_dialog_content = "So... Would you like breakfast when you return? Tweety and I are going to the market to buy some nice ingredients.",
  ui_story_5003_50030301_17_dialog_content = "You are too kind. But we'll just eat out.",
  ui_story_5003_50030301_18_dialog_content = "Alright, alright.",
  ui_story_5003_50030301_19_dialog_content = "PlayerName, let's start our investigation with the hotel.",
  ui_story_5003_50030301_20_dialog_content = "Actually, we took advantage of our time in the hot spring yesterday to ask Tweety about the hotel.",
  ui_story_5003_50030301_21_dialog_content = "We didn't learn of anything suspicious. Although the granny runs the hotel, she isn't the owner.",
  ui_story_5003_50030301_22_dialog_content = "Generally speaking, there's nothing strange about buying land to build a new business on.",
  ui_story_5003_50030301_23_dialog_content = "However, there is something special about the land where the dojo was built.",
  ui_story_5003_50030301_24_dialog_content = "In the Far East, we call a place like this \"unhallowed ground.\"",
  ui_story_5003_50030301_25_dialog_content = "You see, people tend to stay clear of places where gruesome incidents have taken place.",
  ui_story_5003_50030301_26_dialog_content = "Stay clear of them? The hotel does seem like it doesn't have any other guests.",
  ui_story_5003_50030301_27_dialog_content = "The Sakae Family was almost wiped out overnight. A fire burned down the dojo, leaving only ruins in its place.",
  ui_story_5003_50030301_28_dialog_content = "Who would be willing to buy land soaked in blood and build a hot spring hotel with no customers?",
  ui_story_5003_50030301_29_dialog_content = "We need to find the investor. Granny told us that he can be found on Spa Street.",
  ui_story_5003_50030301_30_dialog_content = "His name is...",
  ui_story_5003_50030301_31_option_content = "Taki! I know him!",
  ui_story_5003_50030301_32_dialog_content = "PlayerName, how did you know the investor's name?",
  ui_story_5003_50030301_33_dialog_content = "He told me he was an investor yesterday! Hiiro, he's the one who \"sparred\" with you! Your old dojo-mate!",
  ui_story_5003_50030301_34_dialog_content = "That guy?",
  ui_story_5003_50030301_35_dialog_content = "Where were you yesterday? How did you run into him?",
  ui_story_5003_50030301_36_dialog_content = "I met him in the hotel. I said hi, and we ended up chatting.",
  ui_story_5003_50030301_37_dialog_content = "Didn't you ask him about the hotel?",
  ui_story_5003_50030301_38_dialog_content = "Not really... Our conversation was interrupted when I saw someone running outside the hotel.",
  ui_story_5003_50030301_39_dialog_content = "Sorry, I really thought you were peeping at us when you were standing outside the women's baths yesterday.",
  ui_story_5003_50030301_40_dialog_content = "Well, of course I wasn't! I was just worried that if something had happened, you'd have been caught off-guard...",
  ui_story_5003_50030301_41_dialog_content = "So I decided to go in first and see what was going on.",
  ui_story_5003_50030301_42_dialog_content = "Eh? Is it reawwy twue that you peeping yestewday??",
  ui_story_5003_50030301_43_dialog_content = "No, I was just listening... I mean, no! I didn't see a thing!",
  ui_story_5003_50030301_44_dialog_content = "Tweety, what are you doing here?",
  ui_story_5003_50030301_45_dialog_content = "It's my turn to gets the gwoceries!",
  ui_story_5003_50030301_46_dialog_content = "So Tweety's also in charge of grocery shopping.",
  ui_story_5003_50030301_47_dialog_content = "Tweety, do you know Taki?",
  ui_story_5003_50030301_48_dialog_content = "I knows Taki! I can wook for him if you need me to!",
  ui_story_5003_50030301_49_dialog_content = "Alright, we're counting on you to help us find him.",
  ui_story_5003_50030301_50_dialog_content = "So, we've been on the street all day and found nothing again, just like yesterday...",
  ui_story_5003_50030301_51_dialog_content = "How stwange... I can't find Mister Taki today... Did Mister disappear in a puff of smoke?",
  ui_story_5003_50030301_52_dialog_content = "Taki was awound Spa Street the last few days... Maybe he wents somewhere else today?",
  ui_story_5003_50030301_53_dialog_content = "He was <color=#FFB400>hanging around Spa Street</color>? What was he doing?",
  ui_story_5003_50030301_54_dialog_content = "Mister Taki says it's been a while since he came back so he wanted to lark awound and would come back late.",
  ui_story_5003_50030301_55_dialog_content = "Wook at the time... How abouts evewyone flock back and rest first?",
  ui_story_5003_50030301_56_dialog_content = "I will give a chirp when Mister Taki returns.",
  ui_story_5003_50030301_57_dialog_content = "If he hears that we want to see him... He's likely to suspect something and avoid meeting us.",
  ui_story_5003_50030301_58_option_content = "I think you're right.",
  ui_story_5003_50030301_59_dialog_content = "When we met yesterday, he was a little surprised and asked, \"Didn't you just arrive at the springs?\"",
  ui_story_5003_50030301_60_option_content = "I don't think so.",
  ui_story_5003_50030301_61_dialog_content = "When I saw Taki yesterday, he looked very calm when talking about the dojo.",
  ui_story_5003_50030301_62_dialog_content = "I don't think he has anything to hide.",
  ui_story_5003_50030301_63_dialog_content = "Well, maybe Mr. Taki has already returned to the hotel?",
  ui_story_5003_50030301_64_dialog_content = "Perhaps we didn't see him on the street because we just missed him...?",
  ui_story_5003_50030301_65_dialog_content = "Twue, twue!",
  ui_story_5003_50030301_66_dialog_content = "So, when Taki returns to the hotel, you'll inform us first thing, right, Tweety?",
  ui_story_5003_50030301_67_dialog_content = "Of course! You can twust me!",
  ui_story_5003_50030301_68_dialog_content = "Alright, let's go back to the hotel, then.",
  ui_story_5003_50030301_69_dialog_content = "PlayerName, can I ask you to keep an eye out for anything strange?",
  ui_story_5003_50030301_70_dialog_content = "Anything strange?",
  ui_story_5003_50030301_71_dialog_content = "That's right. I believe your psychic ability may come in handy here.",
  ui_story_5003_50030301_72_dialog_content = "Okay. I understand.",
  ui_story_5003_50030301_73_dialog_content = "Gha... Graaaah...",
  ui_story_5003_50030301_74_dialog_content = "Erm... I think I just heard something strange coming from...",
  ui_story_5003_50030301_75_dialog_content = "*Roar*",
  ui_story_5003_50030301_76_dialog_content = "Ahhh! Ecwipsites!",
  ui_story_5003_50030301_77_dialog_content = "*Roaring*",
  ui_story_5003_50030301_78_dialog_content = "How? What awe these Ecwipsites doing in Spa Street?",
  ui_story_5003_50030301_79_dialog_content = "Oh no! There are too many of them!",
  ui_story_5003_50030301_80_dialog_content = "These Ecwipsites awen't that tough! I can hewp!",
  ui_story_5003_50030301_81_dialog_content = "Move back! Head to the hotel! The path is narrow here! Block it!",
  ui_story_5003_50030301_82_dialog_content = "PlayerName, go and inform Granny. We'll take care of the Eclipsites outside!",
  ui_story_5003_50030301_83_dialog_content = "Alright!",
  ui_story_5003_50030301_84_dialog_content = "*Roaring*",
  ui_story_5003_50030301_85_dialog_content = "Oh no! Commander Hiiro! Eclipsites are heading down the street!",
  ui_story_5003_50030301_86_dialog_content = "I'll stop them!",
  ui_story_5003_50030301_87_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_88_dialog_content = "Who's hiding there? Show yourself!",
  ui_story_5003_50030301_89_dialog_content = "We meet again, Hiiro.",
  ui_story_5003_50030301_90_dialog_content = "Ma'am! Ma'am, where are you? Ma'am!?",
  ui_story_5003_50030301_91_dialog_content = "Strange... There's no one in the hotel?",
  ui_story_5003_50030301_92_dialog_content = "Wait...",
  ui_story_5003_50030301_X92_dialog_content = "Who's hiding in the courtyard? Show yourself!",
  ui_story_5003_50030301_93_dialog_content = "You're...",
  ui_story_5003_50030301_94_dialog_content = "...",
  ui_story_5003_50030301_95_dialog_content = "You're the guy who came running outside last night, aren't you?",
  ui_story_5003_50030301_96_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_97_dialog_content = "The Eclipsites have almost been defeated. What was it you wanted to talk to me about? Go ahead and say it.",
  ui_story_5003_50030301_98_dialog_content = "Taki, why would you build a hotel on the grounds of the Sakae Dojo?",
  ui_story_5003_50030301_99_dialog_content = "The only reason I can think of is that you wanted to hide something.",
  ui_story_5003_50030301_100_dialog_content = "The Sakae Dojo is no more. The land was available, so naturally, I bought it.",
  ui_story_5003_50030301_101_dialog_content = "What did you say!?",
  ui_story_5003_50030301_102_dialog_content = "Calm down. If you're going to let your emotions get the better of you, I advise you to forget this line of questioning.",
  ui_story_5003_50030301_103_dialog_content = "The Sakae Family was slaughtered by its <color=#FFB400>enemies</color>. Master had no choice but to flee with me, and you want me to calm down?",
  ui_story_5003_50030301_104_dialog_content = "<size=45>I'm here for revenge!</size>",
  ui_story_5003_50030301_105_dialog_content = "You can't even tell friend from foe right now. I already told you, I'm your fellow disciple.",
  ui_story_5003_50030301_106_dialog_content = "See this scar on my face? This was left by your master, the head of the Sakae Dojo, <color=#FFB400>Sakae Shigeo</color>.",
  ui_story_5003_50030301_107_dialog_content = "My master? But why?",
  ui_story_5003_50030301_108_dialog_content = "Sakae Shigeo thought I was too scrawny and weak. The look in his eyes told me he wouldn't accept me as a disciple.",
  ui_story_5003_50030301_109_dialog_content = "So I attacked him... and he cut me, but he also admitted that I had potential.",
  ui_story_5003_50030301_110_dialog_content = "So he accepted you as a disciple of the Sakae Dojo?",
  ui_story_5003_50030301_111_dialog_content = "Right. I swore to Sakae Shigeo that if I couldn't beat him within three years, I'd leave of my own volition.",
  ui_story_5003_50030301_112_dialog_content = "And that I'd tell no one that I was a disciple of the Sakae clan so as not to bring shame to Sakae.",
  ui_story_5003_50030301_113_dialog_content = "Did you win in the end?",
  ui_story_5003_50030301_114_dialog_content = "No, he let me win... In the end, I left Cloud Mountain and went to the mainland.",
  ui_story_5003_50030301_115_dialog_content = "I haven't told anyone that I'm a disciple of the Sakae clan, so I don't like being suspected for no reason.",
  ui_story_5003_50030301_116_dialog_content = "You're the one who attacked me first. I only suspected you because I didn't know the truth.",
  ui_story_5003_50030301_117_dialog_content = "We were only sparring. I wasn't trying to hurt you. Even if you didn't know me, you should know the Sakae style.",
  ui_story_5003_50030301_118_dialog_content = "I didn't get the news until after the Sakae Dojo fell.",
  ui_story_5003_50030301_119_dialog_content = "So all I could do was buy the land where the dojo stood so that it wouldn't fall into anyone else's hands.",
  ui_story_5003_50030301_120_dialog_content = "When we first met, you said <color=#FFB400>\"Cloud Mountain is safe now.\"</color> What did you mean by that?",
  ui_story_5003_50030301_121_dialog_content = "I did some investigating. The assailants of the dojo are already gone.",
  ui_story_5003_50030301_122_dialog_content = "What happened to them?",
  ui_story_5003_50030301_123_dialog_content = "They were killed. Or perhaps the disciples of Sakae Dojo fought valiantly, and perished during battle.",
  ui_story_5003_50030301_124_dialog_content = "Perished together in battle? So, you mean... My foes were already defeated before I returned?",
  ui_story_5003_50030301_125_dialog_content = "Correct. It's all over.",
  ui_story_5003_50030301_126_dialog_content = "We're from the same dojo, after all. I'm telling you this because I don't want to see you enslaved by the past.",
  ui_story_5003_50030301_127_dialog_content = "...",
  ui_story_5003_50030301_128_dialog_content = "Granny came to me and said that she wanted to build a hotel.",
  ui_story_5003_50030301_129_dialog_content = "You mean... You're not the one who wanted to build a hotel on this land? It was her?",
  ui_story_5003_50030301_130_dialog_content = "What was she trying to hide by building a hotel on the ruins of the dojo?",
  ui_story_5003_50030401_1_dialog_content = "Silly child... What are you doing collapsed on my doorstep like this? Haven't had a good meal in a long time, eh?",
  ui_story_5003_50030401_2_dialog_content = "Are you... the one who was standing guard two days ago?",
  ui_story_5003_50030401_3_dialog_content = "That's right... You think I'm too old to put up a fight?",
  ui_story_5003_50030401_4_dialog_content = "You must be joking...",
  ui_story_5003_50030401_X4_dialog_content = "<size=45>I let you off easy! Do you really think you're better than me!?</size>",
  ui_story_5003_50030401_5_dialog_content = "Hehe, calm down and come on in. Supper's ready.",
  ui_story_5003_50030401_6_dialog_content = "You're letting me in?",
  ui_story_5003_50030401_7_dialog_content = "How could I not let you in.",
  ui_story_5003_50030401_X7_dialog_content = "This is a hotel...",
  ui_story_5003_50030401_8_dialog_content = "Where am I? Who are you?",
  ui_story_5003_50030401_9_dialog_content = "This is a dojo. I am Sanki.",
  ui_story_5003_50030401_10_dialog_content = "Why did you tie me up? What are you going to do to me?",
  ui_story_5003_50030401_11_dialog_content = "I had to stop you from flailing around.",
  ui_story_5003_50030401_12_dialog_content = "So, what are you going to do to me?",
  ui_story_5003_50030401_13_dialog_content = "Be quiet. You think I'm a fool? I'm the one asking the questions here.",
  ui_story_5003_50030401_14_dialog_content = "Fine, if you say so... But what did you mean when you said this is a dojo?",
  ui_story_5003_50030401_15_dialog_content = "I thought the dojo was destroyed a long time ago. This can't be the place.",
  ui_story_5003_50030401_16_dialog_content = "This can't be the dojo, eh?",
  ui_story_5003_50030401_X16_dialog_content = "Hahahaha!",
  ui_story_5003_50030401_17_dialog_content = "You've never seen the dojo. It seems you really don't know anything.",
  ui_story_5003_50030401_S18_dialog_content = "The dojo was destroyed, but part of it still lies hidden beneath Cloud Blossom Hotel.",
  ui_story_5003_50030401_S19_dialog_content = "Sorry, I really don't know anything... Why don't you tell me more?",
  ui_story_5003_50030401_S20_dialog_content = "Shut it! I've said enough! Do you think I'm some kind of fool!?",
  ui_story_5003_50030401_S21_dialog_content = "Sorry! It's okay if you don't want to talk about the dojo. Let's change the subject.",
  ui_story_5003_50030401_X18_dialog_content = "Your blade is so cool. Does everyone in the Far East have a sword?",
  ui_story_5003_50030401_19_dialog_content = "I told you to shut up! I wasn't even looking for you! So stop trying to talk to me!",
  ui_story_5003_50030401_20_dialog_content = "...!",
  ui_story_5003_50030401_21_dialog_content = "(This guy actually hit someone... If I knew... I would have stopped talking.)",
  ui_story_5003_50030401_22_dialog_content = "PlayerName? PlayerName? Where are you?",
  ui_story_5003_50030401_23_dialog_content = "PlayerName? Gwammy? Where are you?",
  ui_story_5003_50030401_24_dialog_content = "Vice, what's going on?",
  ui_story_5003_50030401_25_dialog_content = "PlayerName and Granny aren't in the hotel... But PlayerName was heading in this direction just now...",
  ui_story_5003_50030401_26_dialog_content = "Let's take another look...",
  ui_story_5003_50030401_27_dialog_content = "Vice! Hiiwo! Twouble!",
  ui_story_5003_50030401_28_dialog_content = "What's up?",
  ui_story_5003_50030401_29_dialog_content = "I couwd nots find Gwammy, but founds a note!",
  ui_story_5003_50030401_30_dialog_content = "Descendant of the Sakura Family: Leave Cloud Mountain immediately!",
  ui_story_5003_50030401_X30_dialog_content = "Otherwise, something terrible will happen to you and your fellow travelers!",
  ui_story_5003_50030401_31_dialog_content = "In addition, if you ever want to see PlayerName alive again, go to Spa Street and wait.",
  ui_story_5003_50030401_32_dialog_content = "Someone's taken PlayerName hostage!?",
  ui_story_5003_50030401_33_dialog_content = "<color=#e8d9bb>*shake, shake... crack, crack...*</color>",
  ui_story_5003_50030401_34_dialog_content = "(It sounds like something's... <color=#FFB400>shaking</color>?)",
  ui_story_5003_50030401_35_dialog_content = "... Who's out there!?",
  ui_story_5003_50030401_36_dialog_content = "(Is that sound coming from outside...? Sanki... He went out!)",
  ui_story_5003_50030401_37_dialog_content = "(Now's my chance to find a way out of this mess!)",
  ui_story_5003_50030401_38_dialog_content = "(I can barely move... Wait a minute, I can call someone with my psychic abilities!)",
  ui_story_5003_50030401_39_dialog_content = "<color=#e8d9bb>*click... click... shoom...*</color>",
  ui_story_5003_50030401_40_dialog_content = "(No way... He's back already?)",
  ui_story_5003_50030401_41_dialog_content = "Wait... That's...!",
  ui_story_5003_50030401_42_dialog_content = "Granny!?",
  ui_story_5003_50030401_43_dialog_content = "Hush, quiet now, child.",
  ui_story_5003_50030401_44_dialog_content = "What are you doing here?",
  ui_story_5003_50030401_45_dialog_content = "We can talk about that later. Let me untie these ropes first... Let's get out of here.",
  ui_story_5003_50030401_46_dialog_content = "What's going on here?",
  ui_story_5003_50030401_47_dialog_content = "My child, I hope you don't blame Sanki for what he did. <color=#FFB400>He just wants to protect Cloud Mountain</color>.",
  ui_story_5003_50030401_48_dialog_content = "Protect it from what?",
  ui_story_5003_50030401_49_dialog_content = "Sorry, but I can't tell you all the secrets of Cloud Mountain. I can, however, explain part of the reason to you.",
  ui_story_5003_50030401_50_dialog_content = "Cloud Mountain is protected by the outer barrier, but your arrival here has somehow affected it, causing the Eclipsites to invade.",
  ui_story_5003_50030401_51_dialog_content = "Sanki was trying to force you to leave because you brought danger to Cloud Mountain...",
  ui_story_5003_50030401_52_dialog_content = "I've already given him a scolding. I hope you can forgive him for what he did.",
  ui_story_5003_50030401_53_dialog_content = "But I don't understand... Why would our presence here affect the barrier?",
  ui_story_5003_50030401_54_dialog_content = "Let's go outside first. I'll explain it to you when we meet up with Hiiro, okay?",
  ui_story_5003_50030401_55_dialog_content = "Okay.",
  ui_story_5003_50030401_56_dialog_content = "PlayerName? Where were you? We've been looking for you for ages!",
  ui_story_5003_50030401_57_dialog_content = "You... didn't you go to Spa Street to wait?",
  ui_story_5003_50030401_58_dialog_content = "Spa Street?",
  ui_story_5003_50030401_59_dialog_content = "It seems Granny wrote the note asking us to leave...",
  ui_story_5003_50030401_60_dialog_content = "I'm sorry... But I just thought it would be best if you left Cloud Mountain.",
  ui_story_5003_50030401_61_dialog_content = "Can you explain what's going on here, Granny?",
  ui_story_5003_50030401_62_dialog_content = "Why did you build a hotel on the ruins of the dojo?",
  ui_story_5003_50030401_63_dialog_content = "Well, I built the hotel to protect the dojo.",
  ui_story_5003_50030401_65_dialog_content = "I suppose there's no way I can hide it from you, but this is only between Hiiro and those she trusts.",
  ui_story_5003_50030401_66_dialog_content = "Come with me, Tweety.",
  ui_story_5003_50030401_67_dialog_content = "Alwight. Don't worry, Gwammy! I'll watch over the stweet! I won't wet anyone in!",
  ui_story_5003_50030401_68_dialog_content = "Good child. Thank you.",
  ui_story_5003_50030401_69_dialog_content = "You shouldn't have come back, Hiiro.",
  ui_story_5003_50030401_70_dialog_content = "Sakae Shigeo wouldn't have allowed you to come back.",
  ui_story_5003_50030401_71_dialog_content = "Granny... Just who are you?",
  ui_story_5003_50030401_72_dialog_content = "When I was young, I used to be the butler of the Sakura Family, and also a messenger that delivers secret information.",
  ui_story_5003_50030401_73_dialog_content = "The Sakura Family and the Sakae Family were the two main forces guarding the Cloud Mountain barrier.",
  ui_story_5003_50030401_74_dialog_content = "The two families invited the most skilled carpenter in all Underwell to build a secret room in the dojo.",
  ui_story_5003_50030401_75_dialog_content = "They sealed something very important there... Something that contains great power and maintains the barrier.",
  ui_story_5003_50030401_76_dialog_content = "Only when both families are here can their blood be used to lift the seal.",
  ui_story_5003_50030401_77_dialog_content = "But once the seal is lifted, the stability of the barrier will be destroyed by the great power of this \"important object.\"",
  ui_story_5003_50030401_78_dialog_content = "And Eclipsites will flood in like an avalanche.",
  ui_story_5003_50030401_79_dialog_content = "Desperate to acquire this \"object\", <color=#FFB400>Far East's evil forces' resentment against the Sakae Family</color> grew...",
  ui_story_5003_50030401_80_dialog_content = "On that fateful night, the Sakae Dojo was attacked.",
  ui_story_5003_50030401_81_dialog_content = "<color=#FFB400>The secret room lies underground</color>, and the seal was soaked with the blood of the Sakae family.",
  ui_story_5003_50030401_82_dialog_content = "Hiiro, as the last of our bloodline, merely standing here will affect the seal.",
  ui_story_5003_50030401_83_dialog_content = "I merely returned to Cloud Mountain to investigate things about the Sakae Family.",
  ui_story_5003_50030401_84_dialog_content = "<size=45>Your existence represents the greatest secret of the Sakae and Sakura Family</size>.",
  ui_story_5003_50030401_85_dialog_content = "I recognized you as soon as I saw you. You remind me of your mother, and your grandmother.",
  ui_story_5003_50030401_86_dialog_content = "I grew up with your grandmother... but they all died long ago.",
  ui_story_5003_50030401_87_dialog_content = "This is a letter from your mother. It's proof that what I've said is true.",
  ui_story_5003_50030401_88_dialog_content = "Now go... Stay away from here before the Eclipsites mount another attack.",
  ui_story_5003_50030401_89_dialog_content = "So as long as I leave, Cloud Mountain will be safe?",
  ui_story_5003_50030401_90_dialog_content = "Yes.",
  ui_story_5003_50030401_91_option_content = "Why don't you leave with us?",
  ui_story_5003_50030401_92_dialog_content = "Please forgive me, but I cannot go with you.",
  ui_story_5003_50030401_93_dialog_content = "I must stay here to guard the hotel, and the secret room beneath it.",
  ui_story_5003_50030401_94_option_content = "Hiiro, what are you going to do?",
  ui_story_5003_50030401_95_dialog_content = "I see. Knowing that you are here has made this whole journey worthwhile.",
  ui_story_5003_50030401_96_dialog_content = "I'll leave Cloud Mountain, but I'm afraid the Eclipsites will invade again...",
  ui_story_5003_50030401_97_dialog_content = "So, I'd like to ask Vice and PlayerName to stay here for the time being to ensure everyone's safety.",
  ui_story_5003_50030401_98_dialog_content = "Wait... Without the Colossus... How do you intend to leave here alone, Hiiro?",
  ui_story_5003_50030401_99_dialog_content = "Don't worry. I'll head to the port by myself.",
  ui_story_5003_50030401_100_dialog_content = "Hiiro, the people here are very troubled by your presence...",
  ui_story_5003_50030401_101_dialog_content = "They're saying that you brought the Eclipsites and calamity to Cloud Mountain.",
  ui_story_5003_50030401_102_dialog_content = "Sanki even attacked PlayerName.",
  ui_story_5003_50030401_X102_dialog_content = "That's why I think you should all leave together...",
  ui_story_5003_50030401_103_dialog_content = "I never thought our trip to Cloud Mountain would end this way...",
  ui_story_5003_50030401_104_dialog_content = "Hush, don't mention it PlayerName, or you'll upset Commander Hiiro.",
  ui_story_5003_50030401_105_dialog_content = "You don't have to worry about me. I'm fine with however this journey ends.",
  ui_story_5003_50030401_106_dialog_content = "We got to meet Mr. Taki and Tweety. That should make things much easier for us if we need to investigate Cloud Mountain in the future.",
  ui_story_5003_50030401_107_dialog_content = "And I read that letter. I believe what Granny said is true.",
  ui_story_5003_50030401_108_dialog_content = "I learned of her story, and of my family's history. The journey was worth it.",
  ui_story_5003_50030401_109_dialog_content = "That's great. Commander Hiiro, you can finally leave Cloud Mountain with a smile.",
  ui_story_5003_50030401_110_dialog_content = "Why do you say that?",
  ui_story_5003_50030401_111_dialog_content = "I feel like you've been stressed out all this time. I've been a little worried about you...",
  ui_story_5003_50030401_112_dialog_content = "Thank you for your concern.",
  ui_story_5003_50030401_113_dialog_content = "At first, I did have some... suspicions, but I know that everything will be alright.",
  ui_story_5003_50030401_114_dialog_content = "My master said he didn't want me to go back to Cloud Mountain, but he didn't tell me why.",
  ui_story_5003_50030401_115_dialog_content = "Thinking about it now, perhaps he just wanted to protect me.",
  ui_story_5003_50030401_116_dialog_content = "However, when my master died, his last wish was for me to \"find my future in the blade of the Sakae.\"",
  ui_story_5003_50030401_117_dialog_content = "I didn't understand what this meant, but after my Sakae Blade began to change, I became determined to return to Cloud Mountain.",
  ui_story_5003_50030401_118_dialog_content = "Even though I still don't understand why, as long as I continue pursuing the secrets of the Sakae Blade, I will one day understand.",
  ui_story_5003_50030401_119_dialog_content = "It's just that it seems like I won't be able to calm its <color=#FFB400>vibrations</color> just yet...",
  ui_story_5003_50030401_120_dialog_content = "Wait.. What do you mean by \"calm its vibrations\"?",
  ui_story_5003_50030401_121_dialog_content = "I can feel it shaking. Maybe it sounds ridiculous.",
  ui_story_5003_50030401_122_dialog_content = "But that's just what happened. First it was seven days ago, then a few hours ago it shook again. This is the third time now.",
  ui_story_5003_50030401_123_dialog_content = "<color=#e8d9bb>*Brrr*</color>",
  ui_story_5003_50030401_124_dialog_content = "That buzzing... Is that the blade vibrating?",
  ui_story_5003_50030401_125_dialog_content = "Hiiro, this sound... I think I heard it before in the dojo.",
  ui_story_5003_50030401_126_dialog_content = "Sanki's weapon was shaking just like your Sakae Blade!",
  ui_story_5003_50030401_127_dialog_content = "But that cannot be... Unless his blade...",
  ui_story_5003_50030401_128_dialog_content = "Is also a <color=#FFB400>Sakae Blade</color>!?",
  ui_story_5003_50030401_129_dialog_content = "Only searing flames and the blood of the Sakae can transform a katana into a Sakae Blade.",
  ui_story_5003_50030401_130_dialog_content = "The evil forces who attacked the Sakae Family, my enemies...",
  ui_story_5003_50030401_131_dialog_content = "<size=45>Their swords were covered in the blood of the Sakae, and they set fire to our home!</size>",
  ui_story_5003_50030401_X131_dialog_content = "You mean, Sanki is one of those enemies!?",
  ui_story_5003_50030501_1_dialog_content = "PlayerName, it's the only possibility I can think of. He has a Sakae Blade!",
  ui_story_5003_50030501_2_dialog_content = "Master told me before he died that this sword was bathed in the blood of the Sakae.",
  ui_story_5003_50030501_3_dialog_content = "After tempering it in flames, the blade will be reborn and become a Sakae Blade.",
  ui_story_5003_50030501_4_dialog_content = "The evil forces of the Far East who slaughtered the Sakae Family... The ones we called our enemies...",
  ui_story_5003_50030501_5_dialog_content = "Their swords were covered in the blood of the Sakae, and they set fire to our home!",
  ui_story_5003_50030501_6_dialog_content = "But Granny must've known about Sanki, so why didn't she tell us?",
  ui_story_5003_50030501_7_dialog_content = "Granny is just a caretaker of the family, she told me she doesn't know much about Sakae.",
  ui_story_5003_50030501_8_dialog_content = "Maybe she doesn't know Sanki's true identity?",
  ui_story_5003_50030501_9_dialog_content = "PlayerName, we must return to Cloud Mountain at once!",
  ui_story_5003_50030501_10_dialog_content = "Do you know how much blood I have spilled for this day?",
  ui_story_5003_50030501_11_dialog_content = "Look at these blades... <color=#FFB400>Every time I get close to the seal, they begin to shake</color>! And roar!",
  ui_story_5003_50030501_12_dialog_content = "Now I only need one last thing—Sakura Family's Hiiro!",
  ui_story_5003_50030501_13_dialog_content = "Then I can finally fulfill what I've longed for all these years!",
  ui_story_5003_50030501_14_dialog_content = "How dare you let her go!?",
  ui_story_5003_50030501_15_dialog_content = "Calm down, Sanki. Let me explain...",
  ui_story_5003_50030501_16_dialog_content = "You want me to calm down? You want me to listen to more of your lies!?",
  ui_story_5003_50030501_17_dialog_content = "You deliberately led me away and let that guy go, and then you let Hiiro leave! That's what you did!",
  ui_story_5003_50030501_18_dialog_content = "You know who I was from the first day we met! You've been planning to stop me all along, haven't you!",
  ui_story_5003_50030501_19_dialog_content = "I wasn't planning on killing you, so you think you can beat me? Is that it?",
  ui_story_5003_50030501_20_dialog_content = "No, listen to me. You can't destroy that thing protected by the seal. Once you destroy it, Cloud Mountain will...",
  ui_story_5003_50030501_21_dialog_content = "Shut up! I don't want to hear another word from you!",
  ui_story_5003_50030501_X21_dialog_content = "You really don't think I'm going to kill you, do you?",
  ui_story_5003_50030501_X23_dialog_content = "Give me your blood.",
  ui_story_5003_50030501_22_dialog_content = "Sanki, I told you before—I'm not a member of the Sakura Family!",
  ui_story_5003_50030501_23_dialog_content = "But I haven't tried your blood yet!",
  ui_story_5003_50030501_X22_dialog_content = "I will never forget the wrath of Underwell...",
  ui_story_5003_50030501_24_dialog_content = "Isn't it natural that the defeated should give up their lives? If you lose, you should pay the price in blood.",
  ui_story_5003_50030501_25_dialog_content = "And once I open the door and destroy what's inside, my revenge will be complete.",
  ui_story_5003_50030501_26_dialog_content = "Isn't that right... Sakae?",
  ui_story_5003_50030501_27_dialog_content = "I almost forgot why I came, but you reminded me.",
  ui_story_5003_50030501_28_dialog_content = "I should thank you, Hiiro. You walked straight into my hands.",
  ui_story_5003_50030501_29_dialog_content = "Haha... Hahahahaha...",
  ui_story_5003_50030501_30_dialog_content = "Hah... What was it my father said to me the night he left? I've forgotten now.",
  ui_story_5003_50030501_31_dialog_content = "Sanki! Leave her alone!",
  ui_story_5003_50030501_32_dialog_content = "Hiiro!?",
  ui_story_5003_50030501_33_dialog_content = "Hahaha! Look, Granny! Your Hiiro has returned! She came back all by herself!",
  ui_story_5003_50030501_34_dialog_content = "H... Hiiro! Don't be rash...",
  ui_story_5003_50030501_35_dialog_content = "If you have any grudge against me, come at me. There's no need for you to harm her.",
  ui_story_5003_50030501_36_dialog_content = "Of course... As long as you stay here, I'll let her go.",
  ui_story_5003_50030501_37_dialog_content = "Alright, I promise. Vice, PlayerName—protect Granny.",
  ui_story_5003_50030501_38_dialog_content = "Granny, come to me!",
  ui_story_5003_50030501_39_dialog_content = "Don't worry! Sanki won't hurt me! He is not our enemy! He's just the carpenter's son!",
  ui_story_5003_50030501_40_dialog_content = "Shut up! Enough words!",
  ui_story_5003_50030501_41_dialog_content = "Hiiro! After I use your blood to break the seal, I'll tell you everything.",
  ui_story_5003_50030501_42_dialog_content = "I just need you to tell me where the blade in your hand came from... Are you an enemy of my family!?",
  ui_story_5003_50030501_43_dialog_content = "If you are, I will have my revenge!",
  ui_story_5003_50030501_X43_dialog_content = "...",
  ui_story_5003_50030501_X44_dialog_content = "What a joke!",
  ui_story_5003_50030501_X45_dialog_content = "What!?",
  ui_story_5003_50030501_44_dialog_content = "You got some nerve still babbling on about revenge!?",
  ui_story_5003_50030501_45_dialog_content = "The people of Underwell were caught up in the struggle between Sakae and their enemies for no reason, and they were massacred in just one night...",
  ui_story_5003_50030501_46_dialog_content = "I put an end to those evil forces. I killed all of those enemies! Just look at the Sakae Blades in my hands!",
  ui_story_5003_50030501_47_dialog_content = "These blades I took from the enemies are proof of my vengeance! What I did was real revenge!",
  ui_story_5003_50030501_48_dialog_content = "As for you, I'll take your life and use it to destroy <size=45>the source of all of this—the thing behind the seal</size>!",
  ui_story_5003_50030501_49_dialog_content = "I can't let you destroy the important object sealed here! The safety of Cloud Mountain depends on it!",
  ui_story_5003_50030501_50_dialog_content = "Enough talk! Hiiro, you don't deserve the Sakae Blade! Sakae Shigeo, today I claim my eighth blade!",
  ui_story_5003_50030501_51_dialog_content = "The fate of Cloud Mountain and this Sakae Blade... Neither shall fall into your hands!",
  ui_story_5003_50030501_52_dialog_content = "What's wrong? Aren't you the proud disciple of Sakae Shigeo?",
  ui_story_5003_50030501_53_dialog_content = "Hahaha! You can't even fight back!?",
  ui_story_5003_50030501_54_dialog_content = "Hiiro! Focus!",
  ui_story_5003_50030501_55_dialog_content = "Focus your mind and give the blade everything you have.",
  ui_story_5003_50030501_56_dialog_content = "Everything I have...",
  ui_story_5003_50030501_57_dialog_content = "Zakura, Sakae, fleeting power...",
  ui_story_5003_50030501_58_dialog_content = "And a death-fearing determination—these are all that I own.",
  ui_story_5003_50030501_59_dialog_content = "!!!",
  ui_story_5003_50030501_60_dialog_content = "You've lost, Sanki.",
  ui_story_5003_50030501_61_dialog_content = "Haha... *cough*",
  ui_story_5003_50030501_62_dialog_content = "I lost... So, kill me...",
  ui_story_5003_50030501_63_dialog_content = "The winner decides the fate of the defeated. When I kill my enemies, I tell them the same thing.",
  ui_story_5003_50030501_66_dialog_content = "Wait! Hiiro! Don't kill him!",
  ui_story_5003_50030501_67_dialog_content = "I know. He's not my \"enemy\"... Tell me who he is, Granny.",
  ui_story_5003_50030501_68_dialog_content = "He is the son of the Underwell carpenter who built the secret room for the Sakae Family.",
  ui_story_5003_50030501_69_dialog_content = "His family... fell victim to the massacre that night.",
  ui_story_5003_50030501_70_dialog_content = "*Cough* My father... agreed to build the secret chamber...",
  ui_story_5003_50030501_71_dialog_content = "So that I could become a disciple of the Sakae Dojo.",
  ui_story_5003_50030501_72_dialog_content = "It's all because of that thing behind the seal! The cause of all this death and destruction!",
  ui_story_5003_50030501_74_dialog_content = "No, the object sealed here is too important to Cloud Mountain, so everyone sacrificed everything to protect it...",
  ui_story_5003_50030501_75_dialog_content = "Enough of this nonsense! Do it!",
  ui_story_5003_50030501_76_dialog_content = "All right...",
  ui_story_5003_50030501_77_dialog_content = "...",
  ui_story_5003_50030501_S77_dialog_content = "You only cut off my hair?",
  ui_story_5003_50030501_X77_dialog_content = "Why are you doing this!? Why won't you finish me off?",
  ui_story_5003_50030501_X78_dialog_content = "I already finished you off...",
  ui_story_5003_50030501_78_dialog_content = "\"You\" are dead— the \"you\" who was obsessed with revenge has been defeated.",
  ui_story_5003_50030501_79_dialog_content = "I hope you can forget it, and put an end to it... Give up on this idea of destroying the seal.",
  ui_story_5003_50030501_80_dialog_content = "I'd rather you kill me than make me a cowardly deserter like you and Sakae Shigeo!",
  ui_story_5003_50030501_81_dialog_content = "There was a time when I didn't understand how he could flee in such a situation.",
  ui_story_5003_50030501_82_dialog_content = "But Sakae Shigeo... My master... he was never afraid of staring death in the face.",
  ui_story_5003_50030501_X82_dialog_content = "He was trying to take me, the \"key\" to the seal, away from here.",
  ui_story_5003_50030501_83_dialog_content = "Master, did your old wound reopen?!",
  ui_story_5003_50030501_84_dialog_content = "The Eclipsites will be here soon, and no one can defend the path to the shelter but us.",
  ui_story_5003_50030501_85_dialog_content = "But my injury is too grave for me to continue fighting...",
  ui_story_5003_50030501_X85_dialog_content = "It's time for me to die.",
  ui_story_5003_50030501_86_dialog_content = "Hiiro, after I die, take my blade... It will become a true Sakae Blade.",
  ui_story_5003_50030501_87_dialog_content = "Searing flames and the blood of the Sakae... will make this sword extremely powerful. This Sakae Blade...",
  ui_story_5003_50030501_88_dialog_content = "It will make you very powerful. It will grant you the power to defeat the Eclipsites.",
  ui_story_5003_50030501_89_dialog_content = "I hope you can see your great future in the Sakae Blade.",
  ui_story_5003_50030501_90_dialog_content = "Master hoped that I could see the future in the Sakae Blade.",
  ui_story_5003_50030501_91_dialog_content = "But I didn't know what this \"future\" was.",
  ui_story_5003_50030501_92_dialog_content = "I didn't understand until I saw you.",
  ui_story_5003_50030501_93_dialog_content = "What do you mean \"until you saw me\"?",
  ui_story_5003_50030501_94_dialog_content = "Like you, I returned to Cloud Mountain out of hatred.",
  ui_story_5003_50030501_95_dialog_content = "But now I know everything.",
  ui_story_5003_50030501_96_dialog_content = "The sealed object maintains the barrier which protects Cloud Mountain. Everyone died protecting Cloud Mountain.",
  ui_story_5003_50030501_97_dialog_content = "So, I can't let you break the seal and destroy what's in there.",
  ui_story_5003_50030501_98_dialog_content = "But I would never kill you.",
  ui_story_5003_50030501_102_dialog_content = "I recognize your technique. We are from the same school.",
  ui_story_5003_50030501_103_dialog_content = "...",
  ui_story_5003_50030501_104_dialog_content = "Father! Will the Sakae Dojo really accept me?",
  ui_story_5003_50030501_105_dialog_content = "Of course! From next week on, you'll be a disciple of the Sakae Dojo!",
  ui_story_5003_50030501_106_dialog_content = "The Sakae Family is amazing! They protect all of Cloud Mountain. Make sure you study hard after you join them!",
  ui_story_5003_50030501_107_dialog_content = "Okay, Father! I'll do my best!",
  ui_story_5003_50030501_108_dialog_content = "The sun has risen. It's time for me to go to Cloud Mountain. I'll wait for you at the dojo...",
  ui_story_5003_50030501_109_dialog_content = "Well, the sun's up. It's time for me to leave.",
  ui_story_5003_50030501_X109_dialog_content = "My presence here will affect the stability of the seal, so I must never return to Cloud Mountain.",
  ui_story_5003_50030501_X110_dialog_content = "I hope that no one will ever find out what is sealed here and that Cloud Mountain will finally know peace.",
  ui_story_5003_50030501_X111_dialog_content = "If anyone else seeks to break the seal, they'll have to take my blood first.",
  ui_story_5003_50030501_X112_dialog_content = "What about me...?",
  ui_story_5003_50030501_X113_dialog_content = "You can try to take my blood, however many times you want.",
  ui_story_5003_50030501_X114_dialog_content = "But as we're disciples of the Sakae Dojo... I'll only ever consider it \"sparring.\"",
  ui_story_5003_50030501_110_dialog_content = "Hmm... It looks like Sanki doesn't want to come and see you off.",
  ui_story_5003_50030501_111_dialog_content = "It's alright, I didn't expect him to.",
  ui_story_5003_50030501_112_dialog_content = "I taught him a tough lesson in the hopes that he'd give up on his revenge, so I can't blame him for holding a grudge in his heart...",
  ui_story_5003_50030501_113_dialog_content = "Don't worry. I don't think he hates you.",
  ui_story_5003_50030501_S113_dialog_content = "The day he found out about the secret room under the hotel... I had planned to guard the entrance with my life.",
  ui_story_5003_50030501_S114_dialog_content = "But he suddenly put down his weapon and stopped trying to force his way in.",
  ui_story_5003_50030501_S115_dialog_content = "After that, he began wandering around here, constantly asking how things were going at the hotel.",
  ui_story_5003_50030501_S116_dialog_content = "Gradually, he opened up to me about his life and would even help Tweety with her chores.",
  ui_story_5003_50030501_S117_dialog_content = "When I told him that there were no descendants of the Sakura Family remaining, and that the seal could no longer be broken...",
  ui_story_5003_50030501_S118_dialog_content = "I saw him breathe a sigh of relief.",
  ui_story_5003_50030501_S119_dialog_content = "At that moment, I suddenly felt that maybe he also needed a reason to give up on his path of revenge.",
  ui_story_5003_50030501_S120_dialog_content = "I hid your existence from him and didn't tell him the secret of the seal. It was all my fault.",
  ui_story_5003_50030501_S121_dialog_content = "I know that you just wanted to protect the secret of the seal. It's not anyone's fault.",
  ui_story_5003_50030501_114_dialog_content = "Gwammy, Sanki wants to dip in the hot spwings. I told him it wasn't weady yet, but he jumped in to clean it himself.",
  ui_story_5003_50030501_115_dialog_content = "Sanki was holding a buncha swords when he jumped in...",
  ui_story_5003_50030501_116_dialog_content = "Hehe, I think he just wants to clean them off. He'll soon come out with them.",
  ui_story_5003_50030501_117_dialog_content = "He is a good child with a good heart, and he cares about the Cloud Mountain, but his life has not been easy, and his mind is a little confused.",
  ui_story_5003_50030501_S122_dialog_content = "I never believed he would actually hurt us.",
  ui_story_5003_50030501_118_dialog_content = "Although I do have faith in your judgment, I hope you will never again be forced to face such a dangerous matter alone.",
  ui_story_5003_50030501_119_dialog_content = "Tweety, Taki, and I—if you ever need to talk, you have friends you can trust.",
  ui_story_5003_50030501_120_dialog_content = "As for Sanki, you should talk to him about his plans. I'm worried that after Tweety's vacation ends, the hotel will be left short-handed.",
  ui_story_5003_50030501_121_dialog_content = "Perhaps Sanki can stay here and help you with the hotel.",
  ui_story_5003_50030501_122_dialog_content = "Don't worry about whether he sneaks into the dojo again. If anything happens, the Sakae Blade will let me know.",
  ui_story_5003_50030501_123_dialog_content = "Alright, my child. Don't you worry.",
  ui_story_5003_50030501_124_dialog_content = "Well, I never expected you'd bring this much drama with you...",
  ui_story_5003_50030501_125_dialog_content = "Mister Taki, what awe you chirping on abouts?",
  ui_story_5003_50030501_126_dialog_content = "No, no, don't mind me. I'm just on vacation.",
  ui_story_5003_50030501_127_dialog_content = "Goodbye.",
  ui_story_5003_50030501_128_dialog_content = "Mister Taki weft before Hiiwo??",
  ui_story_5003_50030501_129_dialog_content = "I think he's going in the same direction as before. He's heading to Spa Street.",
  ui_story_5003_50030501_130_dialog_content = "Maybe he's off on business, as usual?",
  ui_story_5003_50030501_131_dialog_content = "Wight! Sounds just wike him!",
  ui_story_5003_50030501_132_dialog_content = "It's getting late. I should leave as well.",
  ui_story_5003_50030501_133_dialog_content = "Take care, everyone.",
  ui_story_5003_50030501_134_dialog_content = "Hey! Hiiro!",
  ui_story_5003_50030501_135_dialog_content = "Don't you want your Sakae Blade?",
  ui_story_5003_50030501_136_dialog_content = "My Sakae Blade never leaves my side. I don't understand what you're talking about.",
  ui_story_5003_50030501_137_dialog_content = "I have seven of them here. Don't you want them?",
  ui_story_5003_50030501_138_dialog_content = "Of course not. How could I possibly take your Sakae Blades?",
  ui_story_5003_50030501_139_dialog_content = "<size=30>\"I hope you can see your great future ahead in the Sakae Blade\"...</size>",
  ui_story_5003_50030501_140_dialog_content = "Huh? What did you say?",
  ui_story_5003_50030501_141_dialog_content = "Don't worry, I was just talking to myself.",
  ui_story_5003_50030501_142_dialog_content = "Sanki, my fellow disciple, you must guard the dojo with Granny.",
  ui_story_5003_50030501_143_dialog_content = "I...",
  ui_story_5003_50030501_144_dialog_content = "I trust you.",
  ui_story_5003_50030501_145_dialog_content = "Whatever! If you don't want the blades, just forget it!",
  ui_story_5003_50030501_146_dialog_content = "If you want to guard it, just guard it yourself! Anyway, it's all over for me!",
  ui_story_5003_50030501_147_dialog_content = "Bye!",
  ui_story_5003_50030501_148_dialog_content = "This guy...",
  ui_story_5003_50030501_149_dialog_content = "I'd say his mind is more than a little confused...",
  ui_story_5003_50030501_150_dialog_content = "Commander Hiiro, PlayerName usually calls this kind of person a tsundere.",
  ui_story_5003_50030501_151_dialog_content = "Vice, don't change the subject to me all of a sudden!",
  ui_story_5003_50030501_152_dialog_content = "Vice, PlayerName...",
  ui_story_5003_50030501_153_dialog_content = "Sorry, Commander! We know this isn't the right time to be joking around!",
  ui_story_5003_50030501_154_dialog_content = "That's not what I was going to say.",
  ui_story_5003_50030501_155_dialog_content = "Thank you for your help and faith in me. Let's go. We should head back.",
  ui_story_5003_50030501_156_dialog_content = "Alright, Soroz ready to move out!",
  ui_story_5003_50030501_157_dialog_content = "Safe travels, my children.",
  ui_story_5003_50030501_158_dialog_content = "Bye bye! Don't forgots to send us a letter thwough the Couwier Union!",
  ui_story_5003_50030501_159_dialog_content = "Of course, I'll have someone from the Courier Union to send you letters.",
  ui_story_5003_50030501_160_dialog_content = "Farewell, Cloud Mountain."
}
return config
